#!/usr/bin/env python3
"""
Instalador: endpoints multi-LLM en backend/api/.
"""
import os, base64, shutil
from datetime import datetime

API_DIR = os.path.expanduser('~/Desktop/vortu/backend/api')
MAIN_PY = os.path.expanduser('~/Desktop/vortu/backend/main.py')

if not os.path.exists(API_DIR):
    print(f"ERROR: No existe {API_DIR}")
    exit(1)

FILES_B64 = {
    "api/vera_route_api.py": "",
    "api/vera_routing_admin.py": "",
}

# Backup
backup_dir = os.path.join(API_DIR, '_backup_routing_' + datetime.now().strftime('%Y%m%d_%H%M%S'))
os.makedirs(backup_dir, exist_ok=True)

print(f"Creando archivos en {API_DIR}/")
for relpath, b64 in FILES_B64.items():
    # relpath ya tiene "api/" prefix, lo quitamos
    name = relpath.split('/')[-1]
    path = os.path.join(API_DIR, name)
    if os.path.exists(path):
        shutil.copy(path, os.path.join(backup_dir, name))
        print(f"  ~ {name} (backup)")
    content = base64.b64decode(b64).decode('utf-8')
    with open(path, 'w') as f:
        f.write(content)
    print(f"  + {name}")

# Registrar en main.py
print("\nActualizando main.py...")
with open(MAIN_PY) as f:
    main_content = f.read()

shutil.copy(MAIN_PY, MAIN_PY + '.backup_' + datetime.now().strftime('%H%M%S'))

# Imports
new_imports = []
if 'from api.vera_route_api import router' not in main_content:
    new_imports.append('from api.vera_route_api import router as vera_route_api_router')
if 'from api.vera_routing_admin import router' not in main_content:
    new_imports.append('from api.vera_routing_admin import router as vera_routing_admin_router')

if new_imports:
    # Inserta despues del ultimo "from api."
    lines = main_content.split('\n')
    insert_idx = 0
    for i, line in enumerate(lines):
        if line.startswith('from api.') or line.startswith('from vera.'):
            insert_idx = i + 1
    for imp in new_imports:
        lines.insert(insert_idx, imp)
        insert_idx += 1
    main_content = '\n'.join(lines)

# include_router
new_includes = []
if 'vera_route_api_router' not in main_content.split('app.include_router')[-1]:
    new_includes.append('app.include_router(vera_route_api_router)')
if 'vera_routing_admin_router' not in main_content.split('app.include_router')[-1]:
    new_includes.append('app.include_router(vera_routing_admin_router)')

if new_includes:
    # Inserta despues del ultimo include_router
    lines = main_content.split('\n')
    last_include = 0
    for i, line in enumerate(lines):
        if 'app.include_router' in line:
            last_include = i
    for inc in new_includes:
        lines.insert(last_include + 1, inc)
        last_include += 1
    main_content = '\n'.join(lines)

with open(MAIN_PY, 'w') as f:
    f.write(main_content)

print("  + main.py actualizado (imports + include_router)")
print("\nOK Instalacion completa")
print("\nProximos pasos:")
print("1. Reinicia el backend (Ctrl+C y vuelve a ejecutar uvicorn)")
print("2. Verifica con:")
print('   curl -s "http://localhost:8000/api/vera/route/status" -H "Authorization: Bearer $TOKEN" | python3 -m json.tool')
